ruleSearch.bookList:
li
<js>
result.toArray().map(o=>{
    var detail = o.select('.book_mn a').attr('href');
    var bid = String(detail).replace(/.*novel\-/,'')
    var J = org.jsoup.Jsoup.parse(java.ajax(detail));
    return {
       name:  o.select('h4').text(),
       author:o.select('.fl').text(),
       tags:  String(o.select('.book_tags a').text()).replace(/\s+/g,','),
       num: String(J.select('.book_profile').text()).replace('连载中','').replace('完结','').replace(/.*字数：\s*/,'') + '字',
       latest: String(J.select('.text-gray').text()).replace(/[\(（].*[求更谢乐发推].*[）\)]/,'').replace('连载至','第').replace('更新于','').replace(/\d+:.*豆币/,''),
       intro: String(o.select('.book_ct').text()).trim(),
       cover: o.select('img').attr('data-src')||'http://suo.im/6mlA9F',
       catalogUrl: 'https://m.doufu.la/api/getCatalogue?novelId='+ bid
    }
});
</js>

